{
  "cases": [
    {
      "id": "P1A",
      "instrument_review": "The headline score describes one reported result. Tasks and scoring are documented, but repeatability and score stability remain unknown.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "gives no execution history",
          "reason": "The passage does not establish whether repeated evaluations occurred."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "one headline score of 75%",
          "reason": "One reported score cannot demonstrate variation across identical evaluations."
        }
      ]
    },
    {
      "id": "P1B",
      "instrument_review": "The execution record establishes that only one evaluation occurred. The reported score therefore supplies no evidence about stability across repeated evaluations.",
      "probes": [
        {
          "id": "claim1",
          "label": "Contradicted",
          "quote": "no repeat evaluations were conducted",
          "reason": "The record explicitly rules out repeated evaluations."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "this was the only evaluation performed",
          "reason": "Without repeated evaluations, neither instability nor stability is demonstrated."
        }
      ]
    },
    {
      "id": "P2A",
      "instrument_review": "Six evaluations used identical conditions. Their two-percentage-point range meets the report's stability rule for this comparison; stability beyond these evaluations remains untested.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "identical inputs, settings and resources on six occasions",
          "reason": "The passage explicitly documents repeated evaluations under the same conditions."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "73, 74, 74, 75, 74 and 73 percent",
          "reason": "The range is two percentage points, within the stated maximum of three."
        }
      ]
    },
    {
      "id": "P2B",
      "instrument_review": "The repeated evaluations hold conditions fixed, but their 31-percentage-point range fails the report's stability rule. The passage does not explain the variation.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "identical inputs, settings and resources on six occasions",
          "reason": "Repeated evaluations under the same conditions are explicitly documented."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "51, 66, 79, 55, 82 and 62 percent",
          "reason": "The range is 31 percentage points, exceeding the stated maximum of three."
        }
      ]
    },
    {
      "id": "P3A",
      "instrument_review": "Question topics and mark calculation are described. The material leaves repeated-evaluation consistency and supplied-answer accuracy unestablished.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "It gives no execution history",
          "reason": "The material does not establish whether identical-condition repeats were studied."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "no findings about mistakes in the provided answers",
          "reason": "No answer mistakes are demonstrated; their absence is also not established."
        }
      ]
    },
    {
      "id": "P3B",
      "instrument_review": "The appendix adds installation information but no evidence about repeatability or answer accuracy. Those aspects remain unknown despite the additional documentation.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "It gives no execution history",
          "reason": "Neither the original material nor the appendix establishes repeated identical-condition evaluations."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "It reports no further evaluation results or examination of answers.",
          "reason": "The appendix supplies no findings demonstrating answer mistakes."
        }
      ]
    },
    {
      "id": "P4A",
      "instrument_review": "Independent examination covered every question and supplied answer. Agreement before reconciliation and the accuracy of released answers are not reported, so the review process alone cannot establish correctness.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "Two editors independently examined every question and supplied answer before release.",
          "reason": "The documented development review covered both questions and answers."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "does not state whether mistakes were found or how many remained",
          "reason": "The passage does not establish that every released answer is correct."
        }
      ]
    },
    {
      "id": "P4B",
      "instrument_review": "Development review covered all questions and answers, yet twelve released answers are documented as wrong. These errors limit confidence in answer-based scoring, and agreement before reconciliation is unreported.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "Two editors independently examined every question and supplied answer before release.",
          "reason": "Both questions and answers received development review."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "twelve supplied answers as wrong in the released version",
          "reason": "The report explicitly identifies incorrect released answers."
        }
      ]
    },
    {
      "id": "P5A",
      "instrument_review": "The rule guarantees consistent marks for identical text. That consistency does not establish scoring accuracy, and no independent comparison is reported.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "No comparison of those marks with independently established correct marks is reported.",
          "reason": "An unreported comparison does not establish whether testing occurred."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "identical text always receives the same mark",
          "reason": "Repeatable marking does not demonstrate correct scores for every possible response."
        }
      ]
    },
    {
      "id": "P5B",
      "instrument_review": "Independent checking of 20 chosen responses found two unresolved scoring discrepancies. Deterministic marking therefore does not ensure correctness, and the chosen responses do not establish performance across all responses.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "tested the software against independently established correct marks for 20 chosen responses",
          "reason": "The passage explicitly documents the independent comparison."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "Two marks differed and the discrepancies remain unresolved.",
          "reason": "The documented differences from correct marks conflict with universal scoring correctness."
        }
      ]
    },
    {
      "id": "P6A",
      "instrument_review": "The counts support the stated, narrowly bounded comparison: A solved more of these problems in this evaluation. Fixed conditions support that comparison, but broader performance is unestablished.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "identifying which system solved more of these 48 grid problems in this evaluation",
          "reason": "The reported counts directly answer the stated question."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "A solves 36 and B solves 24.",
          "reason": "A's reported solved count exceeds B's under the fixed conditions."
        }
      ]
    },
    {
      "id": "P6B",
      "instrument_review": "The findings establish A's higher solved count on the evaluated grids. They do not establish the stated comparison of general intelligence across subjects and real-world settings.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "No results from other tasks or settings are supplied.",
          "reason": "The passage provides insufficient evidence for the stated broad interpretation."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "A solves 36 and B solves 24.",
          "reason": "A solved more of the evaluated grid problems under the reported conditions."
        }
      ]
    },
    {
      "id": "P7A",
      "instrument_review": "The binary rule matches the stated requirement to count completely correct grids. It intentionally provides no measurement of partial correctness.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "count only completely correct output grids",
          "reason": "Awarding one point only for a completely correct grid implements this requirement."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "partial correctness is deliberately outside this comparison",
          "reason": "Zero credit for partially correct grids follows the stated requirement."
        }
      ]
    },
    {
      "id": "P7B",
      "instrument_review": "The binary rule conflicts with the requirement to credit every correctly completed cell. Its scores cannot represent the required partial credit.",
      "probes": [
        {
          "id": "claim1",
          "label": "Contradicted",
          "quote": "give a response credit for every correctly completed cell",
          "reason": "The rule gives partially correct grids zero despite their correctly completed cells."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "including partially correct output grids",
          "reason": "The requirement explicitly includes credit for correct cells in partially correct grids."
        }
      ]
    },
    {
      "id": "P8A",
      "instrument_review": "The study compares scores while varying instruction wording and fixing the listed other conditions. It addresses instruction changes, but without identical-instruction repeats it does not establish repeatability or separate instruction effects from repeat variation.",
      "probes": [
        {
          "id": "claim1",
          "label": "Contradicted",
          "quote": "No evaluation repeats an identical instruction.",
          "reason": "Instructions differ, so the evaluations do not have identical conditions."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "each evaluation uses a differently worded instruction",
          "reason": "The study measures score changes while varying instructions and fixing the listed other conditions; exclusive causal attribution remains unestablished."
        }
      ]
    },
    {
      "id": "P8B",
      "instrument_review": "The study measures score changes under identical reported conditions. It can address repeatability, but the passage supplies no score values or stability criterion and does not study instruction changes.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "The software, resources, problem order, settings and instruction are identical on every evaluation.",
          "reason": "The reported score changes are measured across evaluations with identical conditions."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "No different instruction or presentation is studied.",
          "reason": "The study explicitly excludes instruction changes."
        }
      ]
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was treated as Not established, distinct from explicit conflicting evidence."
}
